procedure @@proc@@(p_id in number) is
  l_name varchar2(100);
begin
  dbms_output.put_line('looking up');
  select @@col@@ into l_name from @@tab@@ where id = p_id; -- @expect
  dbms_output.put_line(l_name);
  dbms_output.put_line('lookup finished');
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_v varchar2(50);
begin
  begin
    select @@col@@ -- @expect
      into l_v
      from @@tab@@
     where id = p_id;
  exception
    when value_error then
      l_v := null;
  end;
  dbms_output.put_line(l_v);
end @@proc@@;

function @@proc@@(p_id in number) return varchar2 is
  l_v varchar2(100);
begin
  select @@col@@ -- @expect
    into l_v
    from @@tab@@
   where id = p_id;
  return l_v;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_a varchar2(50);
  l_b varchar2(50);
  l_c date;
begin
  select @@col@@, @@col2@@, created_on -- @expect
    into l_a, l_b, l_c
    from @@tab@@
   where id = p_id;
  dbms_output.put_line(l_a || l_b);
end @@proc@@;

function @@proc@@ return varchar2 is
  l_v varchar2(100);
begin
  select @@col@@ into l_v -- @expect
    from (select @@col@@
            from @@tab@@
           order by @@col2@@ desc)
   where rownum = 1;
  return l_v;
end @@proc@@;

