function @@proc@@(p_id in number) return varchar2 is
  l_name varchar2(100);
begin
  select @@col@@ into l_name from @@tab@@ where id = p_id;
  return l_name;
exception
  when no_data_found then
    return null;
end @@proc@@;

procedure @@proc@@(p_key in varchar2) is
  l_id number;
begin
  begin
    select id
      into l_id
      from @@tab@@
     where @@col@@ = p_key;
    @@proc2@@(l_id);
  end;
exception
  when too_many_rows then
    dbms_output.put_line('ambiguous key');
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_name varchar2(100);
begin
  select @@col@@
    into l_name
    from @@tab@@
   where id = p_id;
  dbms_output.put_line(l_name);
exception
  when others then
    raise;
end @@proc@@;

function @@proc@@(p_key in varchar2) return number is
  l_cnt number;
begin
  select count(*)
    into l_cnt
    from @@tab@@
   where @@col@@ = p_key;
  return l_cnt;
end @@proc@@;

function @@proc@@ return varchar2 is
  l_user varchar2(100);
begin
  select sys_context('userenv', 'session_user')
    into l_user
    from dual;
  return l_user;
end @@proc@@;
